presetParts.perFrame:
dec_med = exp (-2/fps);
dec_slow = exp (-0.3/fps);
beat = bass+ mid+treb; 
avg = avg*dec_slow + beat*(1-dec_slow);
is_beat = above(beat, 2*peak) * above (time, t0+.2);
t0 = is_beat*time + (1-is_beat)*t0;
peak = is_beat * beat + (1-is_beat)*peak*dec_med;
index = (index + is_beat) %16;
index2 = (index2 + is_beat*bnot(index))%2;

q20 = avg;
q21 = beat;
q22 = peak;
q24 = is_beat;
q26 = bass_att + mid_att + treb_att;
q27 = index + 1;
q28 = index2;

k1 =  is_beat*equal(index%2,0);
p1 =  k1*(p1+1) + (1-k1)*p1;
p2 = dec_med * p2+ (1-dec_med)*p1;
rott = p2 * 3.1416/8;

q1 = cos(rott);
q2 = sin(rott);
q3 = -q2;
q4 = q1;

//ds = max ((q26-.2),0);
//step = step + ds/10;

step = step + q24 ;

p3 = p3*dec_slow + (1-dec_slow) * step;
q30 = step;

p4 = dec_slow*p4 + (1-dec_slow)*q27;
q31 = p4;

q12 = time -t0;
monitor = q12;



zoom = 1.2+q1*.2;
rot = -0 ;
